// Frontend/src/hooks/useMessages.js
import { useState, useEffect, useCallback } from 'react';

const API_URL = 'http://localhost:5000/api/messages';

const useMessages = () => {
  const [conversations, setConversations] = useState([]);
  const [messages, setMessages] = useState([]);
  const [currentConversation, setCurrentConversation] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  // Fonction utilitaire pour récupérer les headers avec token dynamique
  const getHeaders = () => {
    const token = localStorage.getItem('token'); // Vérifiez le nom de la clé
    return {
      'Content-Type': 'application/json',
      'Authorization': token ? `Bearer ${token}` : ''
    };
  };

  // Gestionnaire des erreurs 401
  const handleUnauthorized = () => {
    setError('Token invalide ou expiré. Veuillez vous reconnecter.');
    setConversations([]);
    setMessages([]);
    setCurrentConversation(null);
  };

  // Récupérer toutes les conversations
  const fetchConversations = useCallback(async () => {
    try {
      setLoading(true);
      const response = await fetch(`${API_URL}/conversations`, {
        headers: getHeaders()
      });

      if (response.status === 401) {
        handleUnauthorized();
        return;
      }

      const data = await response.json();
      if (data.success) {
        setConversations(data.conversations);
      } else {
        setError(data.message || 'Erreur lors du chargement des conversations');
      }
    } catch (err) {
      console.error('Erreur fetchConversations:', err);
      setError('Erreur lors du chargement des conversations');
    } finally {
      setLoading(false);
    }
  }, []);

  // Récupérer ou créer une conversation
  const getOrCreateConversation = useCallback(async (otherUserId) => {
    try {
      setLoading(true);
      const response = await fetch(`${API_URL}/conversations/create`, {
        method: 'POST',
        headers: getHeaders(),
        body: JSON.stringify({ otherUserId })
      });

      if (response.status === 401) {
        handleUnauthorized();
        return;
      }

      const data = await response.json();
      if (data.success) {
        setCurrentConversation(data.conversation);
        return data.conversation;
      } else {
        setError(data.message || 'Erreur lors de la création de la conversation');
      }
    } catch (err) {
      console.error('Erreur getOrCreateConversation:', err);
      setError('Erreur lors de la création de la conversation');
    } finally {
      setLoading(false);
    }
  }, []);

  // Récupérer les messages d'une conversation
  const fetchMessages = useCallback(async (conversationId) => {
    try {
      setLoading(true);
      const response = await fetch(`${API_URL}/conversations/${conversationId}/messages`, {
        headers: getHeaders()
      });

      if (response.status === 401) {
        handleUnauthorized();
        return;
      }

      const data = await response.json();
      if (data.success) {
        setMessages(data.messages);
        setCurrentConversation(data.conversation);
      } else {
        setError(data.message || 'Erreur lors du chargement des messages');
      }
    } catch (err) {
      console.error('Erreur fetchMessages:', err);
      setError('Erreur lors du chargement des messages');
    } finally {
      setLoading(false);
    }
  }, []);

  // Envoyer un message
  const sendMessage = useCallback(async (conversationId, content) => {
    try {
      const response = await fetch(`${API_URL}/messages`, {
        method: 'POST',
        headers: getHeaders(),
        body: JSON.stringify({ conversationId, content })
      });

      if (response.status === 401) {
        handleUnauthorized();
        return;
      }

      const data = await response.json();
      if (data.success) {
        setMessages(prev => [...prev, data.message]);
        return data.message;
      } else {
        setError(data.message || 'Erreur lors de l\'envoi du message');
      }
    } catch (err) {
      console.error('Erreur sendMessage:', err);
      setError('Erreur lors de l\'envoi du message');
    }
  }, []);

  // Initialiser les conversations au montage
  useEffect(() => {
    const token = localStorage.getItem('token');
    if (token) {
      fetchConversations();
    } else {
      setError('Vous devez vous connecter pour accéder aux messages');
    }
  }, [fetchConversations]);

  return {
    conversations,
    messages,
    currentConversation,
    loading,
    error,
    fetchConversations,
    getOrCreateConversation,
    fetchMessages,
    sendMessage,
    setError,
    setMessages
  };
};

export default useMessages;
